def merge_tool_results(calls, results):
    by_id = {}
    for r in results:
        by_id[r["id"]] = r
    out = []
    seen = set()
    for c in calls:
        cid = c["id"]
        if cid in seen:
            raise ValueError(f"duplicate call id {cid!r}")
        seen.add(cid)
        r = by_id.get(cid)
        if r is None:
            out.append({"id": cid, "status": "pending"})
        else:
            out.append({"id": cid, "status": "done", "content": r.get("content", "")})
    return out

