def summarize_usage(events):
    per_input = {}
    per_output = {}
    for event in events:
        inp = event.get("input", 0)
        out = event.get("output", 0)
        if inp is None:
            inp = 0
        if out is None:
            out = 0
        if inp < 0 or out < 0:
            raise ValueError("token counts must be nonnegative")
        rid = event["request_id"]
        per_input[rid] = max(per_input.get(rid, 0), inp)
        per_output[rid] = max(per_output.get(rid, 0), out)
    return {'input': sum(per_input.values()), 'output': sum(per_output.values())}

